import gzip, io, struct, json, subprocess
b=io.BytesIO(gzip.decompress(subprocess.check_output(["docker","exec","minecraft","cat","/data/world/level.dat"])))
def unpack(fmt):
    return struct.unpack(">"+fmt,b.read(struct.calcsize(">"+fmt)))[0]
def string():
    return b.read(unpack("H")).decode("utf-8")
def tag(t):
    if t in (1,2,3,4,5,6): return unpack({1:"b",2:"h",3:"i",4:"q",5:"f",6:"d"}[t])
    if t==7: return b.read(unpack("i"))
    if t==8: return string()
    if t==9:
        inner=unpack("B"); count=unpack("i")
        return [tag(inner) for _ in range(count)]
    if t==10:
        result={}
        while True:
            inner=unpack("B")
            if inner==0: return result
            name=string(); result[name]=tag(inner)
    if t in (11,12):
        return [unpack("i" if t==11 else "q") for _ in range(unpack("i"))]
    raise ValueError(t)
root=unpack("B"); string(); d=tag(root)["Data"]
print(json.dumps({k:d.get(k) for k in ("LevelName","Time","DayTime","LastPlayed","DataVersion")}|{"seed":d.get("WorldGenSettings",{}).get("seed")}))
